/* The console's disk alone. A thread a file writes generated bytes with the calls the
 * file servers use (NtCreateFile, NtWriteFile at an offset, NtFlushBuffersFile), then
 * reads them back; no socket and no USB card has a part in it, so the figure is the
 * disk's, the file system's and the kernel's cache -- what a server could reach at
 * most with the same chunk size and the same number of files at once. */
#include "disk.h"
#include "kernel.h"

extern void KeQuerySystemTime(s64 *time);
extern u32 NtFlushBuffersFile(void *handle, IO_STATUS_BLOCK *io);
extern u32 NtDeleteFile(OBJECT_ATTRIBUTES *attributes);
extern u32 KeSetPriorityThread(void *thread, u32 priority);
extern u32 KeSetAffinityThread(void *thread, u32 affinity, u32 *previous);

#define CHUNK_MAX_KB    1024u
#define GENERIC_READ    0x80000000u
#define GENERIC_WRITE   0x40000000u
#define SYNCHRONIZE     0x00100000u
#define FILE_SHARE_ALL  7u
#define FILE_OPEN       1u
#define FILE_OVERWRITE_IF 5u
#define FILE_SYNCHRONOUS_IO_NONALERT 0x20u
#define FILE_NON_DIRECTORY_FILE 0x40u
#define OBJ_CASE_INSENSITIVE 0x40u

volatile DISK_STATS disk_stats;

/* As the file servers' threads are (src/servers/common/srv_sys.c): on hardware thread 4
 * at their priority. Left where and as the kernel starts it, a thread got its turn only
 * 17 ms after each write's completion -- 3.7 MB/s at 64 KB a call whatever the disk. */
#define DISK_CPU        4u
#define DISK_PRIORITY   20u

static void placed(void)
{
    void *self;
    u32 previous;

    __asm__ volatile("lwz %0, 0x100(13)" : "=r"(self));
    KeSetAffinityThread(self, 1u << DISK_CPU, &previous);
    KeSetPriorityThread(self, DISK_PRIORITY);
}

static u8 *bytes;                       /* CHUNK_MAX_KB of them, taken once */
static char names[DISK_FILES_MAX][56];
static volatile u32 running;            /* threads still in their pass */
static volatile u32 pass;               /* 1 write, 2 read */

static u32 now_ms(void)
{
    s64 t;

    KeQuerySystemTime(&t);
    return (u32)((u64)t >> 13);         /* 0.8192 ms: no 64-bit division in the plugin */
}

static void fail(u32 status)
{
    if (!disk_stats.status)
        disk_stats.status = status;
}

static void named(OBJECT_ATTRIBUTES *a, ANSI_STRING *name, const char *full)
{
    u32 n = 0;

    while (full[n])
        n++;
    name->Length = (u16)n;
    name->MaximumLength = (u16)(n + 1);
    name->Buffer = full;
    a->RootDirectory = 0;
    a->ObjectName = name;
    a->Attributes = OBJ_CASE_INSENSITIVE;
}

static u32 open(const char *full, u32 access, u32 disposition, void **handle)
{
    ANSI_STRING name;
    OBJECT_ATTRIBUTES a;
    IO_STATUS_BLOCK io;
    u32 args[10];

    named(&a, &name, full);
    io.Status = 0;
    *handle = 0;
    args[0] = (u32)handle;
    args[1] = access | SYNCHRONIZE;
    args[2] = (u32)&a;
    args[3] = (u32)&io;
    args[4] = 0;
    args[5] = 0;
    args[6] = FILE_SHARE_ALL;
    args[7] = disposition;
    args[8] = FILE_NON_DIRECTORY_FILE | FILE_SYNCHRONOUS_IO_NONALERT;
    args[9] = (u32)&NtCreateFile;
    return kcall9(args);
}

/* One file, one pass over it. */
static void one(void *context)
{
    const char *full = (const char *)context;
    u32 chunk = disk_stats.chunk_kb << 10, writing = pass == 1, status;
    u64 size = (u64)disk_stats.file_kb << 10, at = 0;
    IO_STATUS_BLOCK io;
    void *h;

    placed();
    status = open(full, writing ? GENERIC_WRITE : GENERIC_READ,
                  writing ? FILE_OVERWRITE_IF : FILE_OPEN, &h);
    if ((s32)status < 0) {
        fail(status);
    } else {
        while (at < size) {
            s64 offset = (s64)at;
            u32 began = now_ms(), took;

            io.Status = 0;
            io.Information = 0;
            status = writing ? NtWriteFile(h, 0, 0, 0, &io, bytes, chunk, &offset)
                             : NtReadFile(h, 0, 0, 0, &io, bytes, chunk, &offset);
            if ((s32)status < 0 || io.Information != chunk) {
                fail((s32)status < 0 ? status : 0xC0000185u);
                break;
            }
            at += chunk;
            if (writing) {
                took = now_ms() - began;
                if (took > disk_stats.slowest_ms)
                    disk_stats.slowest_ms = took;
                __sync_fetch_and_add(&disk_stats.written_kb, disk_stats.chunk_kb);
            } else {
                __sync_fetch_and_add(&disk_stats.read_kb, disk_stats.chunk_kb);
            }
        }
        if (writing) {
            io.Status = 0;
            NtFlushBuffersFile(h, &io);
        }
        NtClose(h);
    }
    __sync_fetch_and_sub(&running, 1);
}

static void all(u32 which)
{
    void *thread;
    u32 i;

    pass = which;
    disk_stats.state = which;
    running = disk_stats.files;
    for (i = 0; i < disk_stats.files; i++) {
        s32 status = ExCreateThread(&thread, 0, 0, 0, (void *)one, names[i], 2);

        if (status < 0) {
            fail((u32)status);
            __sync_fetch_and_sub(&running, 1);
        } else {
            NtClose(thread);
        }
    }
    while (running) {
        s64 interval = -50000;          /* 5 ms */

        KeDelayExecutionThread(0, 0, &interval);
    }
}

static void run(void *context)
{
    u32 began, i;

    (void)context;
    began = now_ms();
    all(1);
    disk_stats.write_ms = now_ms() - began;
    if (!disk_stats.status) {
        began = now_ms();
        all(2);
        disk_stats.read_ms = now_ms() - began;
    }
    for (i = 0; i < disk_stats.files; i++) {
        ANSI_STRING name;
        OBJECT_ATTRIBUTES a;

        named(&a, &name, names[i]);
        NtDeleteFile(&a);
    }
    disk_stats.state = 3;
}

u32 disk_start(u32 mb, u32 chunk_kb, u32 files)
{
    static const char stem[] = "\\Device\\Harddisk0\\Partition1\\xedrivers-disk-";
    void *thread;
    u32 i, k, seed = 0x9E3779B9u;

    if (disk_stats.state == 1 || disk_stats.state == 2)
        return 1;                       /* one at a time */
    if (!mb || !chunk_kb || chunk_kb > CHUNK_MAX_KB || !files || files > DISK_FILES_MAX)
        return 2;
    if (!bytes) {
        bytes = (u8 *)MmAllocatePhysicalMemory(2, CHUNK_MAX_KB << 10, 4);
        if (!bytes)
            return 3;
        for (i = 0; i < CHUNK_MAX_KB << 10; i += 4) {
            seed ^= seed << 13; seed ^= seed >> 17; seed ^= seed << 5;
            *(u32 *)(bytes + i) = seed;
        }
    }
    for (i = 0; i < files; i++) {
        for (k = 0; stem[k]; k++)
            names[i][k] = stem[k];
        names[i][k++] = (char)('0' + i);
        names[i][k++] = '.'; names[i][k++] = 'b'; names[i][k++] = 'i'; names[i][k++] = 'n';
        names[i][k] = 0;
    }
    for (i = 0; i < sizeof(disk_stats) / 4; i++)
        ((volatile u32 *)&disk_stats)[i] = 0;
    disk_stats.files = files;
    disk_stats.chunk_kb = chunk_kb;
    disk_stats.file_kb = ((mb << 10) / files) / chunk_kb * chunk_kb;
    disk_stats.state = 1;
    if (ExCreateThread(&thread, 0, 0, 0, (void *)run, 0, 2) < 0) {
        disk_stats.state = 0;
        return 4;
    }
    NtClose(thread);
    return 0;
}
